package com.prashant.KhetWallah.review;

import com.prashant.KhetWallah.admin.*;
import com.prashant.KhetWallah.listing.*;
import com.prashant.KhetWallah.order.*;
import com.prashant.KhetWallah.user.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.data.domain.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

class OrderReviewServiceTest {
 final OrderReviewRepository reviews=mock(OrderReviewRepository.class);final OrderRepository orders=mock(OrderRepository.class);final ListingRepository listings=mock(ListingRepository.class);final AppUserRepository users=mock(AppUserRepository.class);final AdminActionRepository actions=mock(AdminActionRepository.class);
 final OrderReviewService service=new OrderReviewService(reviews,orders,listings,users,actions);
 final OrderEntity order=mock(OrderEntity.class);final AppUser buyer=mock(AppUser.class),farmer=mock(AppUser.class),admin=mock(AppUser.class);final ListingEntity listing=mock(ListingEntity.class);
 @BeforeEach void setup(){when(buyer.getId()).thenReturn(2L);when(buyer.getDisplayName()).thenReturn("Buyer");when(farmer.getId()).thenReturn(1L);when(admin.getRole()).thenReturn(UserRole.ADMIN);when(users.findByEmail("buyer@example.test")).thenReturn(Optional.of(buyer));when(users.findByEmail("farmer@example.test")).thenReturn(Optional.of(farmer));when(users.findByEmail("admin@example.test")).thenReturn(Optional.of(admin));when(order.getBuyer()).thenReturn(buyer);when(order.getListing()).thenReturn(listing);when(order.getStatus()).thenReturn(OrderStatus.COMPLETED);when(order.getId()).thenReturn(10L);when(listing.getId()).thenReturn(5L);when(listing.getStatus()).thenReturn(ListingStatus.ACTIVE);when(listing.isPubliclyAvailable()).thenReturn(true);when(orders.findByIdForUpdate(10L)).thenReturn(Optional.of(order));when(orders.findById(10L)).thenReturn(Optional.of(order));when(reviews.save(any())).thenAnswer(c->c.getArgument(0));}
 @Test void onlyCompletedOrderBuyerCanPublishOneReview(){var result=service.create(10L,new CreateReviewRequest(5," Good produce "),"buyer@example.test");assertEquals(5,result.rating());assertEquals("Good produce",result.comment());assertEquals("Buyer",result.buyerName());verify(orders).findByIdForUpdate(10L);}
 @Test void farmerAndOtherUsersCannotReviewBuyersOrder(){var ex=assertThrows(ResponseStatusException.class,()->service.create(10L,new CreateReviewRequest(5,"Good"),"farmer@example.test"));assertEquals(404,ex.getStatusCode().value());verify(reviews,never()).save(any());}
 @Test void pendingAndAcceptedOrdersCannotBeReviewed(){for(OrderStatus status:List.of(OrderStatus.PENDING,OrderStatus.ACCEPTED,OrderStatus.CANCELLED,OrderStatus.REJECTED)){when(order.getStatus()).thenReturn(status);var ex=assertThrows(ResponseStatusException.class,()->service.create(10L,new CreateReviewRequest(5,"Good"),"buyer@example.test"));assertEquals(409,ex.getStatusCode().value());}verify(reviews,never()).save(any());}
 @Test void duplicateReviewIsRejected(){OrderReview existing=new OrderReview(order,4,"Good");when(reviews.findByOrder_Id(10L)).thenReturn(Optional.of(existing));assertThrows(ResponseStatusException.class,()->service.create(10L,new CreateReviewRequest(5,"Again"),"buyer@example.test"));verify(reviews,never()).save(any());}
 @Test void ratingAndCommentAreValidatedEvenOutsideController(){for(int rating:new int[]{0,6})assertThrows(ResponseStatusException.class,()->service.create(10L,new CreateReviewRequest(rating,"Good"),"buyer@example.test"));for(String comment:Arrays.asList(null," ","x".repeat(1001)))assertThrows(ResponseStatusException.class,()->service.create(10L,new CreateReviewRequest(5,comment),"buyer@example.test"));verify(reviews,never()).save(any());}
 @Test void publicSummaryUsesOnlyVisibleReviews(){when(listings.findById(5L)).thenReturn(Optional.of(listing));OrderReview existing=new OrderReview(order,4,"Good");when(reviews.findByListingIdAndHiddenFalseOrderByIdDesc(eq(5L),any())).thenReturn(new PageImpl<>(List.of(existing)));when(reviews.averageVisible(5L)).thenReturn(4.0);when(reviews.countByListingIdAndHiddenFalse(5L)).thenReturn(1L);var result=service.publicReviews(5L,0,5);assertEquals(1,result.reviewCount());assertEquals(4.0,result.averageRating());assertEquals(1,result.content().size());}
 @Test void hiddenListingReviewsAreNotPublic(){when(listing.getStatus()).thenReturn(ListingStatus.HIDDEN);when(listing.isPubliclyAvailable()).thenReturn(false);when(listings.findById(5L)).thenReturn(Optional.of(listing));var ex=assertThrows(ResponseStatusException.class,()->service.publicReviews(5L,0,5));assertEquals(404,ex.getStatusCode().value());verify(reviews,never()).findByListingIdAndHiddenFalseOrderByIdDesc(any(),any());}
 @Test void eligibilityIsPrivateAndReflectsExistingReview(){assertTrue(service.eligibility(10L,"buyer@example.test").eligible());assertThrows(ResponseStatusException.class,()->service.eligibility(10L,"farmer@example.test"));OrderReview existing=new OrderReview(order,5,"Good");when(reviews.findByOrder_Id(10L)).thenReturn(Optional.of(existing));assertFalse(service.eligibility(10L,"buyer@example.test").eligible());assertNotNull(service.eligibility(10L,"buyer@example.test").review());}
 @Test void adminHideAndRestoreRequireReasonAndWriteAudit(){OrderReview review=new OrderReview(order,3,"Average");when(reviews.findByIdForUpdate(8L)).thenReturn(Optional.of(review));service.moderate(8L,true,"Personal information","admin@example.test");assertTrue(review.isHidden());service.moderate(8L,false,"Issue corrected","admin@example.test");assertFalse(review.isHidden());ArgumentCaptor<AdminAction> cap=ArgumentCaptor.forClass(AdminAction.class);verify(actions,times(2)).save(cap.capture());assertEquals("HIDE_REVIEW",cap.getAllValues().get(0).getAction());assertEquals("RESTORE_REVIEW",cap.getAllValues().get(1).getAction());assertEquals("REVIEW",cap.getValue().getTargetType());}
 @Test void regularAndSuspendedAccountsCannotModerate(){assertThrows(ResponseStatusException.class,()->service.moderate(8L,true,"Reason","buyer@example.test"));when(admin.isSuspended()).thenReturn(true);assertThrows(ResponseStatusException.class,()->service.adminList("admin@example.test",0,20));verify(actions,never()).save(any());}
 @Test void missingModerationReasonAndNoOpAreRejected(){OrderReview review=new OrderReview(order,4,"Fine");when(reviews.findByIdForUpdate(8L)).thenReturn(Optional.of(review));assertThrows(ResponseStatusException.class,()->service.moderate(8L,true," ","admin@example.test"));assertThrows(ResponseStatusException.class,()->service.moderate(8L,false,"No-op","admin@example.test"));verify(actions,never()).save(any());}
 @Test void publicDtoContainsNeitherEmailNorBuyerId(){assertEquals(Set.of("id","rating","comment","buyerName","createdAt"),new HashSet<>(Arrays.stream(OrderReviewService.ReviewView.class.getRecordComponents()).map(java.lang.reflect.RecordComponent::getName).toList()));}
}
